function uiHistory(d,year=2027){const rows=Object.entries(d.draft.clubs).flatMap(([team,club])=>club.bat.data.map(p=>[team,p.name,p.values.avg,p.values.hr,p.values.h,p.values.rbi,p.values.w,p.values.era,p.values.sv,true,true]));const feb=rows.map(row=>row.map((value,i)=>i===3?String(Number(value)+2):value));return {version:1,seasons:{[year]:{latestMonth:year+'-02',months:{[year+'-01']:{generatedAt:year+'-01-31T10:00:00Z',rows,seasonComplete:false},[year+'-02']:{generatedAt:year+'-02-28T10:00:00Z',rows:feb,seasonComplete:true}}}}};}
